--
-- Table structure for table `libro`
--

DROP TABLE IF EXISTS `libro`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `libro` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `ol_work_key` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ej. OL82563W',
  `titulo` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `descripcion` text COLLATE utf8mb4_unicode_ci,
  `anio_primer_publicacion` smallint unsigned DEFAULT NULL,
  `portada_url` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'covers.openlibrary.org/b/id/{cover_i}-M.jpg',
  `imagen` longblob,
  `enlace_lectura` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'https://archive.org/details/{ia} si ebook_access public/borrowable',
  `ebook_access` enum('public','borrowable','printdisabled','no_ebook') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'no_ebook',
  `idioma_principal` char(3) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rating_promedio` decimal(3,2) DEFAULT NULL COMMENT 'Sort by rating',
  `rating_total_votos` int unsigned NOT NULL DEFAULT '0',
  `popularidad` int unsigned NOT NULL DEFAULT '0' COMMENT 'want_to_read_count -> Sort by popularity',
  `sincronizado_en` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `ol_work_key` (`ol_work_key`),
  KEY `idx_libro_titulo` (`titulo`(200)),
  KEY `idx_libro_rating` (`rating_promedio` DESC,`rating_total_votos` DESC),
  KEY `idx_libro_anio` (`anio_primer_publicacion` DESC),
  KEY `idx_libro_pop` (`popularidad` DESC),
  CONSTRAINT `chk_rating` CHECK (((`rating_promedio` is null) or (`rating_promedio` between 0 and 5)))
) ENGINE=InnoDB AUTO_INCREMENT=63 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `libro`
--

LOCK TABLES `libro` WRITE;
/*!40000 ALTER TABLE `libro` DISABLE KEYS */;
