/*!50001 VIEW `vw_libraria_libros` AS select `l`.`id` AS `id`,`l`.`ol_work_key` AS `ol_work_key`,`l`.`titulo` AS `titulo`,group_concat(distinct `a`.`nombre` order by `a`.`nombre` ASC separator ', ') AS `autores`,(select `a2`.`ol_key` from (`libro_autor` `la2` join `autor` `a2` on((`a2`.`id` = `la2`.`autor_id`))) where (`la2`.`libro_id` = `l`.`id`) order by `la2`.`orden` limit 1) AS `autor_key`,(select `e`.`isbn_13` from `edicion` `e` where ((`e`.`libro_id` = `l`.`id`) and (`e`.`isbn_13` is not null)) order by `e`.`id` limit 1) AS `isbn_13`,`l`.`portada_url` AS `portada_url`,`l`.`enlace_lectura` AS `enlace_lectura`,`l`.`anio_primer_publicacion` AS `anio`,`l`.`rating_promedio` AS `rating`,`l`.`rating_total_votos` AS `votos`,`l`.`popularidad` AS `popularidad`,group_concat(distinct `c`.`nombre` order by `c`.`nombre` ASC separator ', ') AS `categorias`,exists(select 1 from (`libro_seccion` `ls` join `seccion` `s` on((`s`.`id` = `ls`.`seccion_id`))) where ((`ls`.`libro_id` = `l`.`id`) and (`s`.`slug` = 'destacados'))) AS `destacado`,exists(select 1 from (`libro_seccion` `ls` join `seccion` `s` on((`s`.`id` = `ls`.`seccion_id`))) where ((`ls`.`libro_id` = `l`.`id`) and (`s`.`slug` = 'novedades'))) AS `novedad`,exists(select 1 from (`libro_seccion` `ls` join `seccion` `s` on((`s`.`id` = `ls`.`seccion_id`))) where ((`ls`.`libro_id` = `l`.`id`) and (`s`.`slug` = 'recomendados'))) AS `recomendado`,exists(select 1 from (`libro_seccion` `ls` join `seccion` `s` on((`s`.`id` = `ls`.`seccion_id`))) where ((`ls`.`libro_id` = `l`.`id`) and (`s`.`slug` = 'carrusel'))) AS `en_carrusel`,(select `ls`.`posicion` from (`libro_seccion` `ls` join `seccion` `s` on((`s`.`id` = `ls`.`seccion_id`))) where ((`ls`.`libro_id` = `l`.`id`) and (`s`.`slug` = 'carrusel')) limit 1) AS `posicion_carrusel` from ((((`libro` `l` join `libro_autor` `la` on((`la`.`libro_id` = `l`.`id`))) join `autor` `a` on((`a`.`id` = `la`.`autor_id`))) left join `libro_categoria` `lc` on((`lc`.`libro_id` = `l`.`id`))) left join `categoria` `c` on((`c`.`id` = `lc`.`categoria_id`))) group by `l`.`id`,`l`.`ol_work_key`,`l`.`titulo`,`l`.`portada_url`,`l`.`enlace_lectura`,`l`.`anio_primer_publicacion`,`l`.`rating_promedio`,`l`.`rating_total_votos`,`l`.`popularidad` */;
